import {
  BOT_UPGRADES_DATA,
  type BotData,
  type BotUpgradeTier,
  getBotPlusStatBoundsByIndex,
  getBotPlusStatValues,
  getBotStatBoundsByIndex,
  getBotStatValues,
} from '../data/bots'
import { buildNormalizerPersistenceSchema } from './local-persistence-types'

export const BOTS_MEDAL_SPLITTER_TAB = 'medal-splitter'

export type BotsCalcsLocalState = {
  activeTab: string
  activeTierByBot: Record<string, BotUpgradeTier>
  labLevels: Record<string, Record<string, number>>
  enteredLevels: Record<string, number[]>
  targetLevels: Record<string, number[]>
  plusEnteredLevels: Record<string, number[]>
  plusTargetLevels: Record<string, number[]>
  labPanel: number | undefined
  startingPanel: number | undefined
  targetPanel: number | undefined
  showStatCumulatives: boolean
  hideCompleted: boolean
  statFilter: number[]
}

const bots: BotData[] = BOT_UPGRADES_DATA

function clampInt(value: unknown, fallback: number, min: number, max: number): number {
  const numberValue = Number(value)
  if (!Number.isFinite(numberValue)) return fallback
  return Math.floor(Math.min(max, Math.max(min, numberValue)))
}

function defaultActiveTierByBot(): Record<string, BotUpgradeTier> {
  return Object.fromEntries(bots.map(bot => [bot.label, 'base'])) as Record<string, BotUpgradeTier>
}

function defaultLabLevels(): Record<string, Record<string, number>> {
  return bots.reduce((acc, bot) => {
    acc[bot.label] = {}
    bot.labInfo.forEach(({ name }) => {
      acc[bot.label][name] = 0
    })
    return acc
  }, {} as Record<string, Record<string, number>>)
}

function defaultEnteredLevels(): Record<string, number[]> {
  return bots.reduce((acc, bot) => {
    const statValues = getBotStatValues(bot)
    acc[bot.label] = statValues.map((_, statIndex) => {
      const bounds = getBotStatBoundsByIndex(bot, statIndex)
      return bounds.min
    })
    return acc
  }, {} as Record<string, number[]>)
}

function defaultTargetLevels(): Record<string, number[]> {
  return bots.reduce((acc, bot) => {
    const statValues = getBotStatValues(bot)
    acc[bot.label] = statValues.map((_, statIndex) => {
      const bounds = getBotStatBoundsByIndex(bot, statIndex)
      return bounds.max
    })
    return acc
  }, {} as Record<string, number[]>)
}

function defaultPlusEnteredLevels(): Record<string, number[]> {
  return bots.reduce((acc, bot) => {
    const statValues = getBotPlusStatValues(bot)
    acc[bot.label] = statValues.map((_, statIndex) => {
      const bounds = getBotPlusStatBoundsByIndex(bot, statIndex)
      return bounds.min
    })
    return acc
  }, {} as Record<string, number[]>)
}

function defaultPlusTargetLevels(): Record<string, number[]> {
  return bots.reduce((acc, bot) => {
    const statValues = getBotPlusStatValues(bot)
    acc[bot.label] = statValues.map((_, statIndex) => {
      const bounds = getBotPlusStatBoundsByIndex(bot, statIndex)
      return bounds.max
    })
    return acc
  }, {} as Record<string, number[]>)
}

export const defaultBotsCalcsLocalState = (): BotsCalcsLocalState => ({
  activeTab: bots[0]?.label || '',
  activeTierByBot: defaultActiveTierByBot(),
  labLevels: defaultLabLevels(),
  enteredLevels: defaultEnteredLevels(),
  targetLevels: defaultTargetLevels(),
  plusEnteredLevels: defaultPlusEnteredLevels(),
  plusTargetLevels: defaultPlusTargetLevels(),
  labPanel: 0,
  startingPanel: 0,
  targetPanel: 0,
  showStatCumulatives: false,
  hideCompleted: false,
  statFilter: [],
})

function isValidActiveTab(value: unknown): value is string {
  return typeof value === 'string' && (value === BOTS_MEDAL_SPLITTER_TAB || bots.some(bot => bot.label === value))
}

function normalizeNumberArray(value: unknown): number[] {
  if (!Array.isArray(value)) return []
  return value
    .map(item => Number(item))
    .filter(item => Number.isFinite(item))
    .map(item => Math.floor(item))
}

function normalizeLabLevels(value: unknown, fallback: Record<string, Record<string, number>>): Record<string, Record<string, number>> {
  const normalized = defaultLabLevels()
  if (!value || typeof value !== 'object') return { ...normalized, ...fallback }

  const source = value as Record<string, unknown>
  for (const bot of bots) {
    const botSource = source[bot.label]
    if (!botSource || typeof botSource !== 'object') continue
    const botRecord = botSource as Record<string, unknown>
    for (const lab of bot.labInfo) {
      const name = lab.name
      const max = Number(lab.maxLevel || 0)
      const fallbackLevel = fallback[bot.label]?.[name] ?? 0
      normalized[bot.label][name] = clampInt(botRecord[name], fallbackLevel, 0, Number.isFinite(max) ? max : 100)
    }
  }

  return normalized
}

function normalizeActiveTierByBot(value: unknown): Record<string, BotUpgradeTier> {
  const fallback = defaultActiveTierByBot()
  if (!value || typeof value !== 'object') return fallback
  const source = value as Record<string, unknown>
  for (const bot of bots) {
    fallback[bot.label] = source[bot.label] === 'plus' ? 'plus' : 'base'
  }
  return fallback
}

function findBotByLabel(botLabel: string): BotData {
  return bots.find(bot => bot.label === botLabel) || bots[0]
}

function normalizeLevelsByBot(
  value: unknown,
  fallback: Record<string, number[]>,
  kind: 'start' | 'target',
  getValues: (botLabel: string) => string[][],
  getBounds: (botLabel: string, statIndex: number) => { min: number; max: number },
): Record<string, number[]> {
  const normalized = Object.fromEntries(
    Object.entries(fallback).map(([bot, levels]) => [bot, [...levels]]),
  ) as Record<string, number[]>
  if (!value || typeof value !== 'object') return normalized
  const source = value as Record<string, unknown>

  for (const bot of bots) {
    const statValues = getValues(bot.label)
    const arr = source[bot.label]
    if (!Array.isArray(arr)) continue
    const next = [...normalized[bot.label]]
    for (let index = 0; index < statValues.length; index += 1) {
      const bounds = getBounds(bot.label, index)
      const max = bounds.max
      const fallbackValue = next[index] ?? bounds.min
      const min = kind === 'target' ? Math.max(bounds.min, next[index] ?? bounds.min) : bounds.min
      next[index] = clampInt(arr[index], fallbackValue, min, max)
    }
    normalized[bot.label] = next
  }

  return normalized
}

export function normalizeBotsCalcsLocalState(
  input: unknown,
  base: BotsCalcsLocalState = defaultBotsCalcsLocalState(),
): BotsCalcsLocalState {
  const data = input && typeof input === 'object' ? input as Record<string, unknown> : {}
  const tab = data.activeTab
  const labPanel = data.labPanel
  const startingPanel = data.startingPanel
  const targetPanel = data.targetPanel

  return {
    activeTab: isValidActiveTab(tab) ? tab : base.activeTab,
    activeTierByBot: normalizeActiveTierByBot(data.activeTierByBot),
    labLevels: normalizeLabLevels(data.labLevels, base.labLevels),
    enteredLevels: normalizeLevelsByBot(
      data.enteredLevels,
      base.enteredLevels,
      'start',
      botLabel => getBotStatValues(findBotByLabel(botLabel)),
      (botLabel, statIndex) => getBotStatBoundsByIndex(findBotByLabel(botLabel), statIndex),
    ),
    targetLevels: normalizeLevelsByBot(
      data.targetLevels,
      base.targetLevels,
      'target',
      botLabel => getBotStatValues(findBotByLabel(botLabel)),
      (botLabel, statIndex) => getBotStatBoundsByIndex(findBotByLabel(botLabel), statIndex),
    ),
    plusEnteredLevels: normalizeLevelsByBot(
      data.plusEnteredLevels,
      base.plusEnteredLevels,
      'start',
      botLabel => getBotPlusStatValues(findBotByLabel(botLabel)),
      (botLabel, statIndex) => getBotPlusStatBoundsByIndex(findBotByLabel(botLabel), statIndex),
    ),
    plusTargetLevels: normalizeLevelsByBot(
      data.plusTargetLevels,
      base.plusTargetLevels,
      'target',
      botLabel => getBotPlusStatValues(findBotByLabel(botLabel)),
      (botLabel, statIndex) => getBotPlusStatBoundsByIndex(findBotByLabel(botLabel), statIndex),
    ),
    labPanel: typeof labPanel === 'number' && Number.isFinite(labPanel) ? Math.floor(labPanel) : base.labPanel,
    startingPanel: typeof startingPanel === 'number' && Number.isFinite(startingPanel) ? Math.floor(startingPanel) : base.startingPanel,
    targetPanel: typeof targetPanel === 'number' && Number.isFinite(targetPanel) ? Math.floor(targetPanel) : base.targetPanel,
    showStatCumulatives: typeof data.showStatCumulatives === 'boolean' ? data.showStatCumulatives : base.showStatCumulatives,
    hideCompleted: typeof data.hideCompleted === 'boolean' ? data.hideCompleted : base.hideCompleted,
    statFilter: normalizeNumberArray(data.statFilter),
  }
}

export const botsCalcsLocalPersistenceSchema = buildNormalizerPersistenceSchema(normalizeBotsCalcsLocalState)
